  function cloneAt(id, sourceId, description, role, observation, source) {
    const record = (window.OAK.PLANT_BY_ID || {})[id];
    if (!record) throw new Error(`Back-garden clone has no matching plant: ${id}`);
    const base = profiles[sourceId];
    profiles[id] = {
      ...base,
      description,
      oakLodge: {
        location: `${record.plant.position} · ${record.plantKey}`,
        added: "Planted for the 2026 container display",
        role,
        observation,
        status: "Compare performance with the matching plant in the other big pot and retain the stronger overwintered crown or cuttings.",
      },
      sources: [source || base.sources[0], OAK_SOURCE],
    };
  }

  cloneAt("bigpot2-lobelia", "bigpot1-lobelia", "The same Waterfall Deep Blue Ice cultivar forms a second blue-and-white cascade around Big Pot 2. Its fine roots make it the pot’s quickest drought indicator, while the semi-trailing habit repeats the edge treatment used in Big Pot 1. A coordinated midsummer trim can refresh both plants without allowing one pot to look abruptly bare.", "Blue-and-white trailing edge for Big Pot 2", "Deep blue flowers with white centres spill beneath the pink Verbena and purple-white Petunia.");
  cloneAt("bigpot2-nepeta", "bigpot1-nepeta", "This second catmint clump supplies hardy grey-green foliage and lavender-blue spikes through the centre of Big Pot 2. It connects the seasonal pink and purple flowers while remaining useful to bees. Because both big pots contain Nepeta, their response to sun, moisture and post-flowering cutting can be compared directly.", "Hardy aromatic filler and bee forage in Big Pot 2", "Lavender-blue spikes repeat the permanent perennial element from Big Pot 1.");
  cloneAt("bigpot2-fuchsia", "bigpot1-fuchsia", "A second ‘Mrs Popple’ anchors the rear of Big Pot 2 with the same scarlet-and-violet single flowers and upright woody framework. Its hardiness is greater than the surrounding bedding, but its roots are still exposed by container culture. Keeping both Fuchsias lets Oak Lodge compare microclimate and retain the better-performing crown after winter.", "Upright scarlet-and-violet anchor in Big Pot 2", "The repeated Fuchsia gives the two large blue pots a deliberate shared structure.");

