  Object.entries(profiles).forEach(([plantId, profile]) => {
    const record = (window.OAK.PLANT_BY_ID || {})[plantId];
    if (!record) throw new Error(`Back-garden profile has no matching plant: ${plantId}`);
    record.plant.profile = profile;
    window.OAK.AUTHORED_PLANT_PROFILES[plantId] = profile;
  });

  window.OAK.BACK_GARDEN_PROFILE_BUILDERS = { add, profiles, RHS };
